import sys
import os
import unittest

# Ensure backend package is importable when running tests from repo root
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), '..')))

from middleware.security import validate_input
from middleware.validators import validate_identifier, safe_int


class SecuritySanitizersTest(unittest.TestCase):

    def test_validate_input_none(self):
        self.assertIsNone(validate_input(None))

    def test_validate_input_html_escape(self):
        self.assertEqual(validate_input('<script>alert(1)</script>'), '&lt;script&gt;alert(1)&lt;/script&gt;')

    def test_validate_input_remove_sql_tokens(self):
        # semicolon is preserved to avoid breaking HTML entities; comment tokens removed
        self.assertEqual(validate_input("hello; --comment/*x*/"), 'hello; commentx')


class ValidatorsWhitelistTest(unittest.TestCase):

    def test_validate_identifier_ok(self):
        self.assertEqual(validate_identifier('user_123'), 'user_123')

    def test_validate_identifier_invalid_chars(self):
        with self.assertRaises(ValueError):
            validate_identifier('drop;table')

    def test_safe_int_ok(self):
        self.assertEqual(safe_int('42'), 42)

    def test_safe_int_invalid(self):
        self.assertIsNone(safe_int('abc'))


if __name__ == '__main__':
    unittest.main()

